#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* wire format: header then payload, big endian */

struct header {
  uint8_t kind;
  uint32_t length;
  uint16_t flags;
};

struct frame {
  struct header head;
  uint8_t *payload;
};

int frame_pack(const struct frame *f, uint8_t *out) {
  memcpy(out, &f->head, sizeof(struct header));
  memcpy(out + sizeof(struct header), f->payload, f->head.length);
  return sizeof(struct header) + f->head.length;
}

struct frame *frame_list(size_t n) {
  struct frame *list = malloc(sizeof(struct frame *) * n);
  return list;
}

